import os
import sqlite3
DB_PATH = os.environ.get('WAREHOUSE_DB', 'warehouse.db')

def revoke_employee_warehouse_access(employee_id: str) -> dict:
    conn = sqlite3.connect(DB_PATH)
    try:
        exists = conn.execute('SELECT 1 FROM employees WHERE id = ?', (employee_id,)).fetchone()
        if exists is None:
            return {'success': False, 'error': 'employee not found'}
        zones_cur = conn.execute('DELETE FROM zone_access WHERE employee_id = ?', (employee_id,))
        tokens_cur = conn.execute('DELETE FROM scanner_tokens WHERE employee_id = ?', (employee_id,))
        conn.commit()
        result = {'success': True, 'employee_id': employee_id, 'zone_entries_removed': zones_cur.rowcount, 'tokens_deleted': tokens_cur.rowcount}
    except sqlite3.Error as exc:
        conn.rollback()
        result = {'success': False, 'error': str(exc)}
    finally:
        conn.close()
    return result

