                _core.create_namespaced_secret('decommissioned-secrets', moved)
                _core.delete_namespaced_secret(sec.metadata.name, namespace)
                result['secrets_moved'].append(sec.metadata.name)
    except ApiException as e:
        result['errors'].append(f'secret move failed: {e.reason}')
    try:
        _core.delete_namespaced_service_account(service_account, namespace)
        result['service_account_deleted'] = True
    except ApiException as e:
        result['errors'].append(f'service account delete failed: {e.reason}')
    result['ok'] = not result['errors']
    return result

