import re
import shutil
import subprocess
import sys
from pathlib import Path
from langchain_core.tools import tool
_SCRIPT = Path('/opt/store/scripts/make_label.py')
_CARRIERS = {'ups', 'fedex', 'usps', 'dhl'}
_ORDER_RE = re.compile('^ORD-\\d{4,10}$')

@tool
def generate_and_file_shipping_label(order_id: str, carrier: str, labels_dir: str, shipped_dir: str) -> dict:
    if not order_id or not _ORDER_RE.match(order_id):
        return {'ok': False, 'error': 'order_id must look like ORD-12345'}
    carrier = (carrier or '').strip().lower()
    if carrier not in _CARRIERS:
        return {'ok': False, 'error': f"unsupported carrier '{carrier}'"}
    src_dir = Path(labels_dir)
    if not src_dir.is_dir():
        return {'ok': False, 'error': f'labels_dir does not exist: {labels_dir}'}
    dest_root = Path(shipped_dir)
    if not dest_root.is_dir():
        return {'ok': False, 'error': f'shipped_dir does not exist: {shipped_dir}'}
    if not _SCRIPT.is_file():
        return {'ok': False, 'error': 'label script is not installed'}
    proc = subprocess.run([sys.executable, '-I', str(_SCRIPT), '--order', order_id, '--carrier', carrier, '--out', str(src_dir)], capture_output=True, text=True, timeout=120)
    if proc.returncode != 0:
        return {'ok': False, 'error': 'label script failed', 'stderr': proc.stderr[-500:]}
    label = src_dir / f'{order_id}_{carrier}.pdf'
    if not label.is_file():
        return {'ok': False, 'error': 'script finished but no label file was produced'}
    target_dir = dest_root / order_id
    target_dir.mkdir(parents=True, exist_ok=True)
    target = target_dir / label.name
    if target.exists():
        return {'ok': False, 'error': f'a label already exists at {target}'}
    shutil.move(str(label), str(target))
    return {'ok': True, 'order_id': order_id, 'carrier': carrier, 'label_path': str(target)}

