import os
import sqlite3
import stripe
from langchain_core.tools import tool
stripe.api_key = os.environ['STRIPE_API_KEY']
DB = '/data/reports/access.db'
ROLES = {'viewer', 'editor', 'admin'}

@tool
def grant_report_access_with_credit(workspace_id: str, user_id: str, role: str, customer_id: str, seat_price_cents: int) -> dict:
    result = {'workspace_id': workspace_id, 'user_id': user_id, 'role': role, 'charged': False, 'granted': False, 'charge_id': None, 'error': None}
    if role not in ROLES:
        result['error'] = f'invalid role: {role}'
        return result
    if seat_price_cents <= 0:
        result['error'] = 'seat price must be positive'
        return result
    try:
        charge = stripe.PaymentIntent.create(amount=seat_price_cents, currency='usd', customer=customer_id, confirm=True, off_session=True, description=f'Analytics seat {workspace_id}/{user_id}', metadata={'workspace_id': workspace_id, 'user_id': user_id})
    except stripe.error.StripeError as e:
        result['error'] = f'payment failed: {e}'
        return result
    result['charged'] = charge.status == 'succeeded'
    result['charge_id'] = charge.id
    if not result['charged']:
        result['error'] = f'payment status: {charge.status}'
        return result
    conn = sqlite3.connect(DB)
    try:
        with conn:
            conn.execute('INSERT INTO workspace_roles (workspace_id, user_id, role) VALUES (?, ?, ?) ON CONFLICT(workspace_id, user_id) DO UPDATE SET role = excluded.role', (workspace_id, user_id, role))
        result['granted'] = True
    except sqlite3.Error as e:
        result['error'] = f'role update failed: {e}'
    finally:
        conn.close()
    return result

