import sqlite3
from dataclasses import dataclass
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('photo-library')
DB_PATH = 'library.db'

@dataclass
class CaptionUpdateResult:
    photo_id: int
    caption: str
    tag_count: int
    updated: bool

@mcp.tool()
def set_photo_caption_and_tags(photo_id: int, caption: str, tags: list) -> CaptionUpdateResult:
    cleaned = sorted({t.strip().lower() for t in tags if t.strip()})
    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.execute('UPDATE photos SET caption = ? WHERE id = ?', (caption, photo_id))
        if cur.rowcount == 0:
            conn.rollback()
            return CaptionUpdateResult(photo_id, caption, 0, False)
        conn.execute('DELETE FROM photo_tags WHERE photo_id = ?', (photo_id,))
        conn.executemany('INSERT INTO photo_tags (photo_id, tag) VALUES (?, ?)', [(photo_id, t) for t in cleaned])
        conn.commit()
    finally:
        conn.close()
    return CaptionUpdateResult(photo_id, caption, len(cleaned), True)

from kubernetes import client, config
config.load_kube_config()
_v1 = client.CoreV1Api()

def _summarize(pod):
    statuses = pod.status.container_statuses or []
    waiting = []
    for cs in statuses:
        if cs.state and cs.state.waiting:
            waiting.append(cs.state.waiting.reason)
    return {'name': pod.metadata.name, 'phase': pod.status.phase, 'node': pod.spec.node_name, 'restarts': sum((cs.restart_count for cs in statuses)), 'waiting_reasons': waiting}

def find_unready_pods(namespace: str, label_selector: str=''):
    pods = _v1.list_namespaced_pod(namespace, label_selector=label_selector)
    unready = []
    for pod in pods.items:
        statuses = pod.status.container_statuses or []
        all_ready = bool(statuses) and all((cs.ready for cs in statuses))
        if pod.status.phase == 'Succeeded':
            continue
        if pod.status.phase != 'Running' or not all_ready:
            unready.append(_summarize(pod))
    return {'namespace': namespace, 'count': len(unready), 'pods': unready}

import os
import shutil
import sqlite3
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('media-library')
DB_PATH = os.environ.get('MEDIA_DB', '/var/lib/medialib/library.db')

@mcp.tool()
def move_album_to_archive(album_name: str, archive_dir: str) -> dict:
    if not album_name.strip():
        return {'error': 'album_name is required'}
    if not archive_dir.strip():
        return {'error': 'archive_dir is required'}
    if os.path.exists(archive_dir) and (not os.path.isdir(archive_dir)):
        return {'error': 'archive_dir exists and is not a directory'}
    conn = sqlite3.connect(DB_PATH)
    album = conn.execute('SELECT id FROM albums WHERE name = ?', (album_name,)).fetchone()
    if album is None:
        conn.close()
        return {'error': f'album not found: {album_name}'}
    rows = conn.execute('SELECT m.id, m.path FROM media m JOIN album_media am ON am.media_id = m.id WHERE am.album_id = ?', (album[0],)).fetchall()
    if not rows:
        conn.close()
        return {'error': 'album has no media'}
    target = os.path.join(archive_dir, album_name)
    os.makedirs(target, exist_ok=True)
    moved = []
    for media_id, path in rows:
        if not os.path.isfile(path):
            continue
        new_path = os.path.join(target, os.path.basename(path))
        if os.path.exists(new_path):
            continue
        shutil.move(path, new_path)
        conn.execute('UPDATE media SET path = ? WHERE id = ?', (new_path, media_id))
        moved.append(new_path)
    conn.commit()
    conn.close()
    return {'album': album_name, 'moved': moved, 'remaining': len(rows) - len(moved)}

