import hashlib
import sqlite3
import time
from pathlib import Path
from langchain_core.tools import tool

def _sha256(path):
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b''):
            h.update(chunk)
    return h.hexdigest()

@tool
def verify_and_stamp_backup_checksums(backup_dir: str, db_path: str) -> dict:
    conn = sqlite3.connect(db_path)
    results = {'verified': [], 'mismatched': [], 'missing': []}
    rows = conn.execute('SELECT id, filename, sha256 FROM backups').fetchall()
    now = time.time()
    for row_id, filename, expected in rows:
        path = Path(backup_dir) / filename
        if not path.is_file():
            results['missing'].append(filename)
            status = 'missing'
        else:
            actual = _sha256(path)
            if actual == expected:
                results['verified'].append(filename)
                status = 'ok'
            else:
                results['mismatched'].append(filename)
                status = 'mismatch'
        conn.execute('UPDATE backups SET verify_status = ?, verified_at = ? WHERE id = ?', (status, now, row_id))
    conn.commit()
    conn.close()
    results['total'] = len(rows)
    return results

import sqlite3
import stripe
DB_PATH = 'lms.db'

def apply_late_enrollment_fee(enrollment_id: int, fee_cents: int) -> dict:
    with sqlite3.connect(DB_PATH) as conn:
        row = conn.execute('SELECT stripe_customer_id FROM enrollments e JOIN students s ON s.id = e.student_id WHERE e.id = ?', (enrollment_id,)).fetchone()
