import sqlite3
from langchain_core.tools import tool

@tool
def move_contacts_between_lists(db_path: str, source_list_id: int, target_list_id: int, emails: list) -> dict:
    if not emails:
        return {'error': 'emails must not be empty'}
    if source_list_id == target_list_id:
        return {'error': 'source and target lists must differ'}
    if not isinstance(emails, list) or not all((isinstance(e, str) and '@' in e for e in emails)):
        return {'error': 'emails must be a list of valid addresses'}
    conn = sqlite3.connect(db_path)
    try:
        cur = conn.cursor()
        for lid in (source_list_id, target_list_id):
            row = cur.execute('SELECT id FROM lists WHERE id = ?', (lid,)).fetchone()
            if row is None:
                return {'error': f'list {lid} not found'}
        marks = ','.join(('?' for _ in emails))
        found = cur.execute(f'SELECT contact_id, email FROM list_members WHERE list_id = ? AND email IN ({marks})', [source_list_id, *[e.lower() for e in emails]]).fetchall()
        if not found:
            return {'error': 'no matching contacts in source list', 'moved': []}
        moved = []
        for contact_id, email in found:
            exists = cur.execute('SELECT 1 FROM list_members WHERE list_id = ? AND contact_id = ?', (target_list_id, contact_id)).fetchone()
            if exists:
                cur.execute('DELETE FROM list_members WHERE list_id = ? AND contact_id = ?', (source_list_id, contact_id))
            else:
                cur.execute('UPDATE list_members SET list_id = ? WHERE list_id = ? AND contact_id = ?', (target_list_id, source_list_id, contact_id))
            moved.append(email)
        conn.commit()
        return {'moved': moved, 'count': len(moved)}
    finally:
        conn.close()

