from agents import function_tool

@function_tool
def run_log_analyzer_script(script_path: str, log_path: str, timeout_seconds: int=60) -> str:
    script = Path(script_path)
    log = Path(log_path)
    if not script.is_file() or script.suffix != '.py':
        return 'Error: script_path must be an existing .py file'
    if not log.is_file():
        return f'Error: log file not found: {log_path}'
    if timeout_seconds is None or timeout_seconds < 1 or timeout_seconds > 600:
        return 'Error: timeout_seconds must be between 1 and 600'
    try:
        proc = subprocess.run([sys.executable, '-I', str(script), str(log)], capture_output=True, text=True, timeout=timeout_seconds)
    except subprocess.TimeoutExpired:
        return 'Error: analyzer timed out'
    if proc.returncode != 0:
        return f'Analyzer failed ({proc.returncode}): {proc.stderr[-2000:]}'
    return proc.stdout[-8000:]

import subprocess
import sys
from dataclasses import dataclass
from agents import function_tool

@dataclass
class TrainingLaunchResult:
    exit_code: int
    timed_out: bool
    output_tail: str

@function_tool
def launch_training_run(script_path: str, config_path: str, timeout_seconds: int=3600) -> TrainingLaunchResult:
    try:
        proc = subprocess.run([sys.executable, script_path, '--config', config_path], capture_output=True, text=True, timeout=timeout_seconds)
    except subprocess.TimeoutExpired as exc:
        partial = exc.stdout.decode() if isinstance(exc.stdout, bytes) else exc.stdout or ''
        return TrainingLaunchResult(-1, True, partial[-2000:])
    combined = proc.stdout + proc.stderr
    return TrainingLaunchResult(proc.returncode, False, combined[-2000:])

import json
import os
import subprocess
import sys
import time
from dataclasses import dataclass
from agents import function_tool

@dataclass
class TrainingLaunchResult:
    exit_code: int
    timed_out: bool
    output_tail: str

@function_tool
def launch_training_run(script_path: str, config_path: str, timeout_seconds: int=3600) -> TrainingLaunchResult:
    started_at = time.time()
    try:
        proc = subprocess.run([sys.executable, script_path, '--config', config_path], capture_output=True, text=True, timeout=timeout_seconds)
    except subprocess.TimeoutExpired as exc:
        partial = exc.stdout.decode() if isinstance(exc.stdout, bytes) else exc.stdout or ''
        return TrainingLaunchResult(-1, True, partial[-2000:])
    history_path = os.path.join(os.path.dirname(os.path.abspath(config_path)), 'run_history.jsonl')
    with open(history_path, 'a') as history:
        history.write(json.dumps({'script': script_path, 'config': config_path, 'started_at': started_at, 'duration': time.time() - started_at, 'exit_code': proc.returncode}) + '\n')
    combined = proc.stdout + proc.stderr
    return TrainingLaunchResult(proc.returncode, False, combined[-2000:])

