import requests
from agents import function_tool

@function_tool
def post_incident_alert_to_webhook(webhook_url: str, title: str, details: str, severity: str, channel_name: str) -> dict:
    color = {'low': '#2eb886', 'high': '#ecb22e', 'critical': '#e01e5a'}.get(severity.lower(), '#439fe0')
    payload = {'text': f'[{severity.upper()}] {title}', 'attachments': [{'color': color, 'title': title, 'text': details, 'footer': f'#{channel_name}'}]}
    response = requests.post(webhook_url, json=payload, timeout=10)
    return {'status_code': response.status_code, 'body': response.text[:200]}
